import{z as p,x as d,o as s,c as A,q as r,j as l,D as i,d as t,s as E,S as n,b as e}from"./chunks/framework.C8m1ZpeB.js";const T=JSON.parse('{"title":"访问者与遍","description":"","frontmatter":{"title":"访问者与遍","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/ast-visitor.md","filePath":"cs/ast-visitor.md","lastUpdated":1791413859000}'),B={name:"cs/ast-visitor.md"};function c(m,a,h,D,f,u){const o=d("Mermaid");return s(),A("div",null,[a[2]||(a[2]=r('<h1 id="访问者与遍" tabindex="-1">访问者与遍 <a class="header-anchor" href="#访问者与遍" aria-label="Permalink to &quot;访问者与遍&quot;">​</a></h1><div class="epigraph"><p>树的形状固定，操作随遍增加：把遍历做成访问者，类型检查、解释、IR 生成各写一组 visit，而不改节点类。</p><footer>—— 据 Gamma et al., Design Patterns, 1994；Appel, Modern Compiler Implementation 整理</footer></div><p>上一课<a href="/cs/ast">抽象语法树</a>交出压缩后的有序树，并声明后课要遍历。本课不重定义 BinOp。缺口是<strong>遍</strong>（pass）怎么挂在树上：递归函数按节点种类分支，或访问者把「对每种节点做什么」从树节点里拆出去。<a href="/cs/compiler-passes">编译器通行证</a>已有管道；本课把管道的前端段落实为 AST 上的多次行走。符号表还没有，visit 遇到 <code>id</code> 仍只看见字符串。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>若每个新分析都改节点类加方法，节点会膨胀成上帝对象。访问者：<code>visit(BinOp)</code>、<code>visit(If)</code>…，双分派或手工 <code>switch</code> 种类。一遍可以综合属性（自底向上求值），一遍可以继承属性（自顶向下传作用域）。语法制导定义里的综合/继承与此对应，本课用遍历实现，不把属性文法公理写完。</p><p><span class="marginnote">「双分派」就是「分两步决定调用哪个函数」：第一步按遍历器选对象，第二步按节点真实类型选 visit。多数语言的调用只看「第一个参数是谁」这一个维度，所以要靠 accept 函数中转一次，把节点类型这个维度补上。</span></p><p>遍的次序：先解析绑定，再类型，再 IR。错序会在未绑定的名字上查类型。本课只钉「多遍、每遍一种职责」，查找规则下一课。</p><h3 id="访问者不是图算法-dfs-的别名" tabindex="-1">访问者不是图算法 DFS 的别名 <a class="header-anchor" href="#访问者不是图算法-dfs-的别名" aria-label="Permalink to &quot;访问者不是图算法 DFS 的别名&quot;">​</a></h3><p>AST 是树，一般无共享（公共子表达式前）。遍历是树递归，不是 CFG 上的数据流。不要把后课活跃变量的迭代当成 visit 一遍就结束。</p><p><span class="marginnote">GoF Visitor。Appel 的每章一棵树加一组 visit。龙书用语法制导，动作写在产生式上，与归约时构造 AST 是同一遍历的不同时机。本课允许分析期再走树，不必全在归约瞬间做完。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>定义节点代数数据类型。写 <code>Visitor</code>：默认递归孩子，再覆盖要做事的种类。遍与遍之间可把结果写回节点字段（类型、绑定指针）或另建并行结构。错误继续遍历以便多报。</p><p><span class="marginnote">直觉类比：访问者像景区检票——树是固定的景点地图，「学生半价、儿童免票」这类规则随活动常换；换检票方案（新的 visitor）不必改建景点（节点类）。若把规则写成景点自带的字段，每办一次活动就得拆一次墙。</span></p>',13)),(s(),l(n,null,{default:i(()=>[E(o,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20AST%5B%22AST%22%5D%20--%3E%20V1%5B%22%E9%81%8D%EF%BC%9A%E7%BB%93%E6%9E%84%E6%A3%80%E6%9F%A5%22%5D%0A%20%20V1%20--%3E%20V2%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E7%BB%91%E5%AE%9A%22%5D%0A%20%20V2%20--%3E%20V3%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E7%B1%BB%E5%9E%8B%20%2F%20IR%22%5D%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,[e("a",{href:"/cs/tree-as-acyclic"},"树"),t(" 的无环保证递归终止。若语言允许图（已有命名类型的环），visit 要备「正在走」标记，那是类型课的名义类型，本课点名。")],-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[t("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,[t("前端管道 = 词法、语法、若干 AST 遍。中端换成 CFG 就不再用本课的树访问者，而用块上的迭代。本课不开始填符号表，但 visit 进入 "),e("code",null,"Block"),t(" 时将是 push 作用域的位置——下一课接。")],-1)),a[6]||(a[6]=e("p",null,"accept 与 visit 两跳到底怎么把调用路由对：",-1)),(s(),l(n,null,{default:i(()=>[E(o,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20L%5B%22%E9%81%8D%E5%8E%86%E5%99%A8%E5%AF%B9%E6%AF%8F%E4%B8%AA%E8%8A%82%E7%82%B9%E8%B0%83%20accept%20v%22%5D%20--%3E%20AC%5B%22%E8%8A%82%E7%82%B9%E8%87%AA%E5%B7%B1%E7%9A%84%20accept%20%E6%8E%A5%E6%89%8B%22%5D%0A%20%20AC%20--%3E%20DD%5B%22%E6%8C%89%E8%8A%82%E7%82%B9%E7%9C%9F%E5%AE%9E%E7%B1%BB%E5%9E%8B%E5%9B%9E%E8%B0%83%20v%20%E7%9A%84%E5%AF%B9%E5%BA%94%20visit%22%5D%0A%20%20DD%20--%3E%20B%5B%22visit%20BinOp%EF%BC%9A%E9%80%92%E5%BD%92%E4%B8%A4%E4%B8%AA%E5%AD%A9%E5%AD%90%E5%86%8D%E5%90%88%E5%B9%B6%E7%BB%93%E6%9E%9C%22%5D%0A%20%20DD%20--%3E%20IF%5B%22visit%20If%EF%BC%9A%E5%85%88%E8%B5%B0%E6%9D%A1%E4%BB%B6%E5%86%8D%E8%B5%B0%E5%88%86%E6%94%AF%22%5D%0A"})]),fallback:i(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=r('<p>不要为了访问者模式把简单编译器写成框架地狱；函数式语言里一组函数定义即访问者。</p><p><span class="marginnote">常见误区：初学者容易以为「visit 一遍就能算出活跃变量这类信息」。AST 访问者只会沿树单向递归；需要反复迭代到不动点的数据流分析住在中端的 CFG 上，别把两件事塞进同一把刷子。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不解析名字、不检查类型、不生成三地址。不把解释器当必选遍。后课默认：会对 AST 走遍。作用域与符号表层叠是下一缺口。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>遍 = 对 AST 的一次职责单一的遍历；访问者把操作从节点拆出。</li><li>综合自底向上，继承自顶向下。</li><li>绑定尚未发生；下一课符号表。</li><li>出处：Gamma et al., 1994；Appel, <em>Modern Compiler Implementation</em>。</li></ul>',6))])}const F=p(B,[["render",c]]);export{T as __pageData,F as default};
